mapper.select:
SELECT r.reorg_key, r.reorg_dt, r.conf_yn, r.use_yn, r.reorg_title, r.remark, COUNT(d.dept_key)::int AS department_count FROM hrm_org_reorg r LEFT JOIN hrm_org_dept d ON d.reorg_key = r.reorg_key AND d.use_yn = 'Y'
AND (r.reorg_title ILIKE '%' || #{keyword} || '%' OR r.remark ILIKE '%' || #{keyword} || '%')
GROUP BY r.reorg_key ORDER BY r.reorg_dt DESC, r.reg_dtm DESC LIMIT #{limit} OFFSET #{offset}

SELECT COALESCE(MAX(sort_order), 0) + 1 FROM hrm_org_dept WHERE reorg_key = #{reorgKey} AND use_yn = 'Y' AND
parent_dept_key = #{parentDeptKey}
parent_dept_key IS NULL
